mapper.select:
SELECT * FROM t_ai_feedback WHERE deleted = 0 AND user_id = #{userId} AND session_id = #{sessionId}
AND LEFT(ai_response, 50) = LEFT(#{aiResponse}, 50)
ORDER BY create_time DESC LIMIT 1

mapper.delete:
UPDATE t_ai_feedback SET deleted = 1, update_time = NOW()
WHERE deleted = 0 AND user_id = #{userId} AND session_id = #{sessionId}
AND LEFT(ai_response, 50) = LEFT(#{aiResponse}, 50)

mapper.select:
SELECT user_message FROM t_ai_feedback
WHERE deleted = 0 AND user_message IS NOT NULL AND LENGTH(user_message) > 2
GROUP BY user_message ORDER BY MAX(create_time) DESC LIMIT #{limit}
